// All expected values in this file were generated by running the
// original Python (QUEENSALLYONLINEBOOKOFMAGIFICATIONANDUNICOR/
// gpt-2/pemdas.py functions, which are pure string manipulation with no
// TF dependency) under python3, or copied from executed notebook cell
// outputs in TOYBOK/COR.ipynb.

func TestSquish(t *testing.T) {
	tests := []struct {
		in, want string
	}{
		{"bananna", "BANANA"},
		{"BANANNA", "BANANA"},
		{"NOW THERE ARE ONLY BIRDS left outside the gate for the public to see",
			"NOWTHEREAREONLYBIRDSLEFTOUTSIDETHEGATEFORTHEPUBLICTOSE"},
		{"NOW WE ARE ONLY BIRDS", "NOWEAREONLYBIRDS"},
		{"STILLIORIALS", "STILIORIALS"},
		{`                    - WHO ELSE SEEN THE LEPRECHAUN?SAY "YEAH"!`,
			"WHOELSESENTHELEPRECHAUNSAYEAH"},
		{"QUEENSALLYONLINEBOOKOFMAGIFICATIONANDUNICOR",
			"QUENSALYONLINEBOKOFMAGIFICATIONANDUNICOR"},
		// Dropped characters do not reset the duplicate window.
		{"a a", "A"},
		{"Mississippi 122 __ !!", "MISISIPI12_"},
		{"", ""},
		{"?!.,", ""},
	}
	for _, tt := range tests {
		if got := Squish(tt.in); got != tt.want {
			t.Errorf("Squish(%q) = %q, want %q", tt.in, got, tt.want)
		}
	}
}

