func TestTower(t *testing.T) {
	tests := []struct {
		in    string
		width int
		want  []string
	}{
		// Notebook cell 26: trxtwr("dinosaur", 3).
		{"dinosaur", 3, []string{"DIN", "OSA", "URX"}},
		{"NOW THERE ARE ONLY BIRDS", 3,
			[]string{"NOW", "THE", "REA", "REO", "NLY", "BIR", "DSX"}},
		{"NOW WE ARE ONLY BIRDS", 3,
			[]string{"NOW", "EAR", "EON", "LYB", "IRD", "SXX"}},
		{"STILLIORIALS", 3, []string{"STI", "LIO", "RIA", "LSX"}},
		{"QUEENSALLYONLINEBOOKOFMAGIFICATIONANDUNICOR", 3,
			[]string{"QUE", "NSA", "LYO", "NLI", "NEB", "OKO", "FMA",
				"GIF", "ICA", "TIO", "NAN", "DUN", "ICO", "RXX"}},
		{"", 3, nil},
	}
	for _, tt := range tests {
		if got := Tower(tt.in, tt.width); !reflect.DeepEqual(got, tt.want) {
			t.Errorf("Tower(%q, %d) = %v, want %v", tt.in, tt.width, got, tt.want)
		}
	}
}

// TestTowerVOIDONX pins the port against the repo's saved real-session
// artifact (VOIDONX): GPT-2 output lines whose tower renderings were
// captured verbatim. VOIDONX shows only the complete leading rows before
// GPT-2's own continuation takes over, so we compare prefixes.
func TestTowerVOIDONX(t *testing.T) {
	tests := []struct {
		in         string
		wantPrefix []string
	}{
		{"NOW THERE ARE ONLY BIRDS",
			[]string{"NOW", "THE", "REA", "REO", "NLY", "BIR"}},
		{"NOW WE ARE ONLY BIRDS",
			[]string{"NOW", "EAR", "EON", "LYB", "IRD"}},
		{"STILLIORIALS", []string{"STI", "LIO", "RIA"}},
	}
	for _, tt := range tests {
		got := Tower(tt.in, TowerWidth)
		if len(got) < len(tt.wantPrefix) ||
			!reflect.DeepEqual(got[:len(tt.wantPrefix)], tt.wantPrefix) {
			t.Errorf("Tower(%q) = %v, want prefix %v", tt.in, got, tt.wantPrefix)
		}
	}
}

